const embedding = $input.first().json.data[0].embedding;

// Query DocChunk nodes â top 10 for comprehensive guide coverage
const body = JSON.stringify({
  statements: [{
    statement: "CALL db.index.vector.queryNodes('atlas_chunk_embeddings', 10, $embedding) YIELD node, score WHERE 'DocChunk' IN labels(node) RETURN node.heading AS heading, node.text AS text, node.title AS title, node.section AS section, score ORDER BY score DESC",
    parameters: { embedding: embedding }
  }]
});

return [{ json: { requestBody: body, embedding: embedding } }];

// Get embedding from the Embed Topic node
const embedding = $('Embed Topic').first().json.data[0].embedding;

// Query SMEKnowledge nodes via RELATED_TO traversal from matching DocChunks
const body = JSON.stringify({
  statements: [{
    statement: "CALL db.index.vector.queryNodes('atlas_chunk_embeddings', 10, $embedding) YIELD node AS chunk, score MATCH (sme:SMEKnowledge)-[:RELATED_TO]->(chunk) RETURN sme.question AS question, sme.answer AS answer, sme.topic AS topic, sme.confidence AS confidence, score ORDER BY score DESC LIMIT 6",
    parameters: { embedding: embedding }
  }]
});

return [{ json: { requestBody: body } }];

// Build doc context from DocChunk results
const docResults = $('Query DocChunks').first().json.results[0].data;
const docChunks = docResults.map(row => {
  const cols = row.row;
  return { heading: cols[0], text: cols[1], title: cols[2], section: cols[3], score: cols[4] };
});

const docContext = docChunks
  .map(c => `## ${c.title} â ${c.heading}\n${c.text}`)
  .join('\n\n---\n\n');

// Build SME context from SMEKnowledge results
const smeResults = $input.first().json.results[0].data;
const smeChunks = smeResults.map(row => {
  const cols = row.row;
  return { question: cols[0], answer: cols[1], topic: cols[2], confidence: cols[3], score: cols[4] };
});

// Deduplicate SME Q&A by question text
const seen = new Set();
const uniqueSme = smeChunks.filter(s => {
  if (seen.has(s.question)) return false;
  seen.add(s.question);
  return true;
});

let smeContext = '';
if (uniqueSme.length > 0) {
  smeContext = uniqueSme
    .map(s => `**Field Q&A â ${s.topic}**\nQ: ${s.question}\nA: ${s.answer}\n_(Confidence: ${s.confidence})_`)
    .join('\n\n---\n\n');
}

return [{ json: { docContext, smeContext, hasSME: uniqueSme.length > 0, smeCount: uniqueSme.length } }];

